/**
 * Convert the message cache of `adapter` to an array of message IDs.
 *
 * @param {LiveViewDataAdapter} adapter
 * @returns {integer[]}
 */
function listMessages(adapter) {
  const ids = [];
  for (let i = 0; i < adapter.rowCount; i++) {
    ids.push(adapter.rowAt(i).message.id);
  }
  return ids;
}

