    info(`rowCountChanged(${index}, ${delta})`);
    Assert.strictEqual(this._index, undefined);
    Assert.strictEqual(this._start, undefined);
    this._index = index;
    this._delta = delta;
    this._rowCountDeferred?.resolve();
