  invalidateRow(index) {
    info(`invalidateRow(${index})`);
    // `invalidateRow` immediately after `rowCountChanged` is allowed.
    Assert.strictEqual(this._start, undefined);
    this._start = index;
    this._end = index;
    this._invalidateDeferred?.resolve();
  }
