    info(`invalidateRange(${start}, ${end})`);
    Assert.strictEqual(this._index, undefined);
    Assert.strictEqual(this._start, undefined);
    this._start = start;
    this._end = end;
    this._invalidateDeferred?.resolve();
  }
  reset() {
    info(`reset()`);
    Assert.ok(false, "reset() should not be called in this test");
  }

